WITH flagged AS (SELECT dateTime FROM archive WHERE rain=0 AND rainRate>0 AND YEAR(FROM_UNIXTIME(dateTime))<>2021), lagged AS (SELECT dateTime,LAG(dateTime) OVER(ORDER BY dateTime) prev_time FROM flagged), marked AS (SELECT dateTime,CASE WHEN prev_time IS NULL OR dateTime-prev_time>600 THEN 1 ELSE 0 END new_group FROM lagged), grouped AS (SELECT dateTime,SUM(new_group) OVER(ORDER BY dateTime ROWS UNBOUNDED PRECEDING) grp FROM marked), episodes AS (SELECT grp,COUNT(*) n,MIN(dateTime) first_epoch,MAX(dateTime) last_epoch,MAX(dateTime)-MIN(dateTime) duration_seconds FROM grouped GROUP BY grp) SELECT YEAR(FROM_UNIXTIME(first_epoch)) local_year,COUNT(*) episodes,SUM(n) records,MAX(n) max_records_in_episode,MAX(duration_seconds) max_duration_seconds,ROUND(AVG(n),2) avg_records_per_episode,MIN(first_epoch) first_episode,MAX(last_epoch) last_episode FROM episodes GROUP BY YEAR(FROM_UNIXTIME(first_epoch)) ORDER BY local_year
